-- 081_budget_ownership_notifications.sql
-- Roadmap E.26: accountable Discipline ownership, least-privilege owner access,
-- append-only assignment history and in-product Budget notifications.

CREATE TABLE IF NOT EXISTS public.project_budget_ownerships(
  budget_cycle_id uuid NOT NULL,project_id bigint NOT NULL,ontology_version_id uuid NOT NULL,discipline_id uuid NOT NULL,
  department_name text NOT NULL CHECK(btrim(department_name)<>'' AND char_length(department_name)<=160),
  owner_user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  revision integer NOT NULL CHECK(revision>0),assigned_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,assigned_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY(budget_cycle_id,discipline_id),
  FOREIGN KEY(budget_cycle_id,project_id,ontology_version_id)REFERENCES public.project_budget_cycles(id,project_id,ontology_version_id)ON DELETE RESTRICT,
  FOREIGN KEY(ontology_version_id,discipline_id)REFERENCES public.work_ontology_disciplines(ontology_version_id,id)ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS project_budget_ownerships_owner_idx ON public.project_budget_ownerships(owner_user_id,assigned_at DESC);

CREATE TABLE IF NOT EXISTS public.project_budget_ownership_events(
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,budget_cycle_id uuid NOT NULL,project_id bigint NOT NULL,discipline_id uuid NOT NULL,
  event_type text NOT NULL CHECK(event_type IN('ASSIGNED','REASSIGNED')),department_name text NOT NULL,owner_user_id uuid NOT NULL REFERENCES auth.users(id)ON DELETE RESTRICT,
  previous_owner_user_id uuid REFERENCES auth.users(id)ON DELETE RESTRICT,ownership_revision integer NOT NULL CHECK(ownership_revision>0),actor_id uuid NOT NULL REFERENCES auth.users(id)ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY(budget_cycle_id,discipline_id)REFERENCES public.project_budget_ownerships(budget_cycle_id,discipline_id)ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS public.project_budget_notifications(
  id uuid PRIMARY KEY,recipient_user_id uuid NOT NULL REFERENCES auth.users(id)ON DELETE RESTRICT,project_id bigint NOT NULL REFERENCES public.projects(id)ON DELETE RESTRICT,
  budget_cycle_id uuid NOT NULL REFERENCES public.project_budget_cycles(id)ON DELETE RESTRICT,discipline_id uuid NOT NULL,
  event_type text NOT NULL CHECK(event_type IN('BUDGET_OWNERSHIP_ASSIGNED','BUDGET_OWNERSHIP_REASSIGNED','BUDGET_OWNERSHIP_REMOVED')),
  message text NOT NULL CHECK(btrim(message)<>''),created_at timestamptz NOT NULL DEFAULT now(),read_at timestamptz,
  UNIQUE(id,recipient_user_id)
);
CREATE INDEX IF NOT EXISTS project_budget_notifications_recipient_idx ON public.project_budget_notifications(recipient_user_id,read_at,created_at DESC);

ALTER TABLE public.project_budget_ownerships ENABLE ROW LEVEL SECURITY;ALTER TABLE public.project_budget_ownership_events ENABLE ROW LEVEL SECURITY;ALTER TABLE public.project_budget_notifications ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS project_budget_ownerships_select ON public.project_budget_ownerships;
CREATE POLICY project_budget_ownerships_select ON public.project_budget_ownerships FOR SELECT TO authenticated USING(owner_user_id=auth.uid()OR(lower((SELECT role FROM public.profiles WHERE id=auth.uid()))IN('pm','admin')AND public.can_write_project(project_id)));
DROP POLICY IF EXISTS project_budget_ownership_events_select ON public.project_budget_ownership_events;
CREATE POLICY project_budget_ownership_events_select ON public.project_budget_ownership_events FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.project_budget_ownerships ownership WHERE ownership.budget_cycle_id=project_budget_ownership_events.budget_cycle_id AND ownership.discipline_id=project_budget_ownership_events.discipline_id AND(ownership.owner_user_id=auth.uid()OR(lower((SELECT role FROM public.profiles WHERE id=auth.uid()))IN('pm','admin')AND public.can_write_project(ownership.project_id)))));
DROP POLICY IF EXISTS project_budget_notifications_select ON public.project_budget_notifications;
CREATE POLICY project_budget_notifications_select ON public.project_budget_notifications FOR SELECT TO authenticated USING(recipient_user_id=auth.uid());
REVOKE ALL ON TABLE public.project_budget_ownerships,public.project_budget_ownership_events,public.project_budget_notifications FROM PUBLIC,anon,authenticated,service_role;
GRANT SELECT ON TABLE public.project_budget_ownerships,public.project_budget_ownership_events,public.project_budget_notifications TO authenticated;
REVOKE ALL ON SEQUENCE public.project_budget_ownership_events_id_seq FROM PUBLIC,anon,authenticated,service_role;

DROP POLICY IF EXISTS project_budget_cycles_select ON public.project_budget_cycles;
CREATE POLICY project_budget_cycles_select ON public.project_budget_cycles FOR SELECT TO authenticated USING((lower((SELECT role FROM public.profiles WHERE id=auth.uid()))IN('pm','admin')AND public.can_write_project(project_id))OR EXISTS(SELECT 1 FROM public.project_budget_ownerships ownership WHERE ownership.budget_cycle_id=project_budget_cycles.id AND ownership.owner_user_id=auth.uid()));
DROP POLICY IF EXISTS project_budget_contributions_select ON public.project_budget_contributions;
CREATE POLICY project_budget_contributions_select ON public.project_budget_contributions FOR SELECT TO authenticated USING((lower((SELECT role FROM public.profiles WHERE id=auth.uid()))IN('pm','admin')AND public.can_write_project(project_id))OR EXISTS(SELECT 1 FROM public.project_budget_ownerships ownership WHERE ownership.budget_cycle_id=project_budget_contributions.budget_cycle_id AND ownership.discipline_id=project_budget_contributions.discipline_id AND ownership.owner_user_id=auth.uid()));

CREATE OR REPLACE FUNCTION public.list_budget_owner_candidates(p_project_id bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$
DECLARE v_uid uuid:=auth.uid();v_project public.projects%ROWTYPE;
BEGIN
 SELECT * INTO v_project FROM public.projects WHERE id=p_project_id;
 IF v_uid IS NULL OR lower((SELECT role FROM public.profiles WHERE id=v_uid))NOT IN('pm','admin')OR public.can_write_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION 'BUDGET_OWNERSHIP_FORBIDDEN' USING ERRCODE='42501';END IF;
 RETURN COALESCE((SELECT jsonb_agg(jsonb_build_object('userId',profile.id,'name',profile.name,'email',profile.email,'role',profile.role)ORDER BY profile.name,profile.email)FROM public.profiles profile WHERE lower(profile.role)IN('pm','viewer')AND(v_project.company_id IS NULL OR profile.company_id=v_project.company_id)),'[]'::jsonb);
END;$$;

CREATE OR REPLACE FUNCTION public.assign_budget_discipline_owner(p_budget_cycle_id uuid,p_discipline_id uuid,p_department_name text,p_owner_user_id uuid,p_expected_revision integer,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_uid uuid:=auth.uid();v_cycle public.project_budget_cycles%ROWTYPE;v_project public.projects%ROWTYPE;v_existing public.project_budget_ownerships%ROWTYPE;v_owner public.profiles%ROWTYPE;v_request public.write_command_requests%ROWTYPE;v_revision integer;v_result jsonb;v_discipline_label text;v_department_label text;
BEGIN
 IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000';END IF;
 IF p_budget_cycle_id IS NULL OR p_discipline_id IS NULL OR p_owner_user_id IS NULL OR p_client_request_id IS NULL OR p_expected_revision IS NULL OR p_expected_revision<0 OR btrim(COALESCE(p_department_name,''))=''OR char_length(btrim(p_department_name))>160 THEN RAISE EXCEPTION 'INVALID_BUDGET_OWNERSHIP_COMMAND' USING ERRCODE='22023';END IF;
 SELECT * INTO v_cycle FROM public.project_budget_cycles WHERE id=p_budget_cycle_id;IF v_cycle.id IS NULL THEN RAISE EXCEPTION 'BUDGET_CYCLE_NOT_FOUND' USING ERRCODE='P0002';END IF;
 IF lower((SELECT role FROM public.profiles WHERE id=v_uid))NOT IN('pm','admin')OR public.can_write_project(v_cycle.project_id)IS NOT TRUE THEN RAISE EXCEPTION 'BUDGET_OWNERSHIP_FORBIDDEN' USING ERRCODE='42501';END IF;
 SELECT * INTO v_project FROM public.projects WHERE id=v_cycle.project_id FOR UPDATE;
 SELECT * INTO v_owner FROM public.profiles WHERE id=p_owner_user_id;IF v_owner.id IS NULL OR lower(v_owner.role)NOT IN('pm','viewer')OR(v_project.company_id IS NOT NULL AND v_owner.company_id IS DISTINCT FROM v_project.company_id)THEN RAISE EXCEPTION 'INVALID_BUDGET_OWNER' USING ERRCODE='22023';END IF;
 SELECT discipline.label,department.label INTO v_discipline_label,v_department_label FROM public.work_ontology_disciplines discipline JOIN public.work_ontology_departments department ON department.ontology_version_id=discipline.ontology_version_id AND department.id=discipline.department_id WHERE discipline.ontology_version_id=v_cycle.ontology_version_id AND discipline.id=p_discipline_id;
 IF v_discipline_label IS NULL OR NOT EXISTS(SELECT 1 FROM public.project_budget_contributions WHERE budget_cycle_id=p_budget_cycle_id AND discipline_id=p_discipline_id)THEN RAISE EXCEPTION 'BUDGET_DISCIPLINE_NOT_IN_CYCLE' USING ERRCODE='22023';END IF;
 INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(v_uid,'budget.assign_owner',p_client_request_id,v_cycle.project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;
 SELECT * INTO v_request FROM public.write_command_requests WHERE actor_id=v_uid AND operation='budget.assign_owner'AND client_request_id=p_client_request_id;
 IF v_request.project_id IS DISTINCT FROM v_cycle.project_id THEN RAISE EXCEPTION 'Idempotency key belongs to another project' USING ERRCODE='23505';END IF;
 IF v_request.response IS NOT NULL THEN IF (v_request.response->>'budgetCycleId')::uuid IS DISTINCT FROM p_budget_cycle_id OR(v_request.response->>'disciplineId')::uuid IS DISTINCT FROM p_discipline_id THEN RAISE EXCEPTION 'Idempotency key belongs to another ownership' USING ERRCODE='23505';END IF;RETURN v_request.response||jsonb_build_object('idempotentReplay',true);END IF;
 SELECT * INTO v_existing FROM public.project_budget_ownerships WHERE budget_cycle_id=p_budget_cycle_id AND discipline_id=p_discipline_id FOR UPDATE;
 IF COALESCE(v_existing.revision,0)<>p_expected_revision THEN RAISE EXCEPTION 'BUDGET_OWNERSHIP_REVISION_CONFLICT' USING ERRCODE='40001';END IF;
 v_revision:=p_expected_revision+1;
 INSERT INTO public.project_budget_ownerships(budget_cycle_id,project_id,ontology_version_id,discipline_id,department_name,owner_user_id,revision,assigned_by,assigned_at)
 VALUES(p_budget_cycle_id,v_cycle.project_id,v_cycle.ontology_version_id,p_discipline_id,v_department_label,p_owner_user_id,v_revision,v_uid,now())
 ON CONFLICT(budget_cycle_id,discipline_id)DO UPDATE SET department_name=EXCLUDED.department_name,owner_user_id=EXCLUDED.owner_user_id,revision=EXCLUDED.revision,assigned_by=EXCLUDED.assigned_by,assigned_at=EXCLUDED.assigned_at;
 INSERT INTO public.project_budget_ownership_events(budget_cycle_id,project_id,discipline_id,event_type,department_name,owner_user_id,previous_owner_user_id,ownership_revision,actor_id)
 VALUES(p_budget_cycle_id,v_cycle.project_id,p_discipline_id,CASE WHEN v_existing.revision IS NULL THEN'ASSIGNED'ELSE'REASSIGNED'END,v_department_label,p_owner_user_id,v_existing.owner_user_id,v_revision,v_uid);
 IF v_existing.owner_user_id IS NOT NULL AND v_existing.owner_user_id<>p_owner_user_id THEN INSERT INTO public.project_budget_notifications(id,recipient_user_id,project_id,budget_cycle_id,discipline_id,event_type,message)VALUES(gen_random_uuid(),v_existing.owner_user_id,v_cycle.project_id,p_budget_cycle_id,p_discipline_id,'BUDGET_OWNERSHIP_REMOVED','Budget ownership removed: '||v_discipline_label);END IF;
 INSERT INTO public.project_budget_notifications(id,recipient_user_id,project_id,budget_cycle_id,discipline_id,event_type,message)VALUES(gen_random_uuid(),p_owner_user_id,v_cycle.project_id,p_budget_cycle_id,p_discipline_id,CASE WHEN v_existing.revision IS NULL THEN'BUDGET_OWNERSHIP_ASSIGNED'ELSE'BUDGET_OWNERSHIP_REASSIGNED'END,'Budget input assigned: '||v_discipline_label||' · '||btrim(p_department_name));
 v_result:=jsonb_build_object('budgetCycleId',p_budget_cycle_id,'disciplineId',p_discipline_id,'departmentName',v_department_label,'ownerUserId',p_owner_user_id,'revision',v_revision);
 UPDATE public.write_command_requests SET response=v_result,completed_at=now()WHERE id=v_request.id;RETURN v_result||jsonb_build_object('idempotentReplay',false);
END;$$;

CREATE OR REPLACE FUNCTION public.get_project_budget_workspace(p_project_id bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$
DECLARE v_uid uuid:=auth.uid();v_project public.projects%ROWTYPE;v_cycle public.project_budget_cycles%ROWTYPE;v_manage boolean;v_total numeric;v_group_count integer;v_submitted_count integer;v_progress_count integer;v_ownerships jsonb;v_contributions jsonb;v_unread integer;
BEGIN
 IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000';END IF;SELECT * INTO v_project FROM public.projects WHERE id=p_project_id;SELECT * INTO v_cycle FROM public.project_budget_cycles WHERE project_id=p_project_id;
 v_manage:=lower((SELECT role FROM public.profiles WHERE id=v_uid))IN('pm','admin')AND public.can_write_project(p_project_id);
 IF v_project.id IS NULL OR(NOT v_manage AND(v_cycle.id IS NULL OR NOT EXISTS(SELECT 1 FROM public.project_budget_ownerships WHERE budget_cycle_id=v_cycle.id AND owner_user_id=v_uid)))THEN RAISE EXCEPTION 'BUDGET_WORKSPACE_FORBIDDEN' USING ERRCODE='42501';END IF;
 IF v_project.work_ontology_version_id IS NULL THEN RAISE EXCEPTION 'PROJECT_BUDGET_REQUIRES_WORK_ONTOLOGY' USING ERRCODE='55000';END IF;
 SELECT COALESCE(sum(c.amount),0),count(*),count(*)FILTER(WHERE c.status='SUBMITTED'),count(*)FILTER(WHERE c.status='IN_PROGRESS')INTO v_total,v_group_count,v_submitted_count,v_progress_count FROM public.project_budget_contributions c WHERE c.budget_cycle_id=v_cycle.id AND(v_manage OR EXISTS(SELECT 1 FROM public.project_budget_ownerships o WHERE o.budget_cycle_id=c.budget_cycle_id AND o.discipline_id=c.discipline_id AND o.owner_user_id=v_uid));
 SELECT COALESCE(jsonb_agg(jsonb_build_object('disciplineId',o.discipline_id,'departmentName',o.department_name,'ownerUserId',o.owner_user_id,'ownerName',profile.name,'ownerEmail',profile.email,'revision',o.revision)ORDER BY d.display_order),'[]'::jsonb)INTO v_ownerships FROM public.project_budget_ownerships o JOIN public.profiles profile ON profile.id=o.owner_user_id JOIN public.work_ontology_disciplines d ON d.ontology_version_id=o.ontology_version_id AND d.id=o.discipline_id WHERE o.budget_cycle_id=v_cycle.id AND(v_manage OR o.owner_user_id=v_uid);
 SELECT COALESCE(jsonb_agg(jsonb_build_object('departmentId',department.id,'departmentCode',department.code,'departmentLabel',department.label,'disciplineId',c.discipline_id,'disciplineCode',d.code,'disciplineLabel',d.label,'workGroupId',c.work_group_id,'workGroupCode',g.code,'workGroupLabel',g.label,'amount',c.amount,'note',c.note,'status',c.status,'revision',c.revision,'updatedBy',c.updated_by,'updatedAt',c.updated_at)ORDER BY department.display_order,d.display_order,g.display_order),'[]'::jsonb)INTO v_contributions FROM public.project_budget_contributions c JOIN public.work_ontology_work_groups g ON g.ontology_version_id=c.ontology_version_id AND g.id=c.work_group_id JOIN public.work_ontology_disciplines d ON d.ontology_version_id=c.ontology_version_id AND d.id=c.discipline_id JOIN public.work_ontology_departments department ON department.ontology_version_id=d.ontology_version_id AND department.id=d.department_id WHERE c.budget_cycle_id=v_cycle.id AND g.is_active AND(v_manage OR EXISTS(SELECT 1 FROM public.project_budget_ownerships o WHERE o.budget_cycle_id=c.budget_cycle_id AND o.discipline_id=c.discipline_id AND o.owner_user_id=v_uid));
 SELECT count(*)INTO v_unread FROM public.project_budget_notifications WHERE budget_cycle_id=v_cycle.id AND recipient_user_id=v_uid AND read_at IS NULL;
 RETURN jsonb_build_object('projectId',p_project_id,'projectCode',v_project.store_code,'projectName',v_project.shopping_mall_name,'projectCurrencyCode',v_project.currency_code,'ontologyVersionId',v_project.work_ontology_version_id,'canManageOwnership',v_manage,'cycle',CASE WHEN v_cycle.id IS NULL THEN NULL ELSE jsonb_build_object('budgetCycleId',v_cycle.id,'title',v_cycle.title,'currencyCode',v_cycle.currency_code,'status',v_cycle.status,'createdAt',v_cycle.created_at)END,'summary',jsonb_build_object('total',v_total,'workGroupCount',v_group_count,'submittedCount',v_submitted_count,'inProgressCount',v_progress_count),'ownerships',v_ownerships,'unreadNotificationCount',v_unread,'contributions',v_contributions);
END;$$;

CREATE OR REPLACE FUNCTION public.save_project_budget_contribution(p_budget_cycle_id uuid,p_work_group_id uuid,p_amount numeric,p_note text,p_status text,p_expected_revision integer,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_uid uuid:=auth.uid();v_manage boolean;v_cycle public.project_budget_cycles%ROWTYPE;v_row public.project_budget_contributions%ROWTYPE;v_request public.write_command_requests%ROWTYPE;v_result jsonb;
BEGIN
 IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000';END IF;IF p_budget_cycle_id IS NULL OR p_work_group_id IS NULL OR p_client_request_id IS NULL OR p_expected_revision IS NULL OR p_expected_revision<0 OR p_status NOT IN('NOT_STARTED','IN_PROGRESS','SUBMITTED')OR char_length(COALESCE(p_note,''))>2000 OR(p_status='NOT_STARTED'AND p_amount IS NOT NULL)OR(p_status<>'NOT_STARTED'AND(p_amount IS NULL OR p_amount<0))THEN RAISE EXCEPTION 'INVALID_BUDGET_CONTRIBUTION_COMMAND' USING ERRCODE='22023';END IF;
 SELECT * INTO v_cycle FROM public.project_budget_cycles WHERE id=p_budget_cycle_id;IF v_cycle.id IS NULL THEN RAISE EXCEPTION 'BUDGET_CYCLE_NOT_FOUND' USING ERRCODE='P0002';END IF;SELECT * INTO v_row FROM public.project_budget_contributions WHERE budget_cycle_id=p_budget_cycle_id AND work_group_id=p_work_group_id;IF v_row.work_group_id IS NULL THEN RAISE EXCEPTION 'BUDGET_WORK_GROUP_NOT_FOUND' USING ERRCODE='P0002';END IF;
 v_manage:=lower((SELECT role FROM public.profiles WHERE id=v_uid))IN('pm','admin')AND public.can_write_project(v_cycle.project_id);
 IF NOT v_manage AND NOT EXISTS(SELECT 1 FROM public.project_budget_ownerships WHERE budget_cycle_id=p_budget_cycle_id AND discipline_id=v_row.discipline_id AND owner_user_id=v_uid)THEN RAISE EXCEPTION 'BUDGET_CONTRIBUTION_FORBIDDEN' USING ERRCODE='42501';END IF;
 INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(v_uid,'budget.save_contribution',p_client_request_id,v_cycle.project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;SELECT * INTO v_request FROM public.write_command_requests WHERE actor_id=v_uid AND operation='budget.save_contribution'AND client_request_id=p_client_request_id;
 IF v_request.project_id IS DISTINCT FROM v_cycle.project_id THEN RAISE EXCEPTION 'Idempotency key belongs to another project' USING ERRCODE='23505';END IF;IF v_request.response IS NOT NULL THEN IF(v_request.response->>'budgetCycleId')::uuid IS DISTINCT FROM p_budget_cycle_id OR(v_request.response->>'workGroupId')::uuid IS DISTINCT FROM p_work_group_id THEN RAISE EXCEPTION 'Idempotency key belongs to another Budget contribution' USING ERRCODE='23505';END IF;RETURN v_request.response||jsonb_build_object('idempotentReplay',true);END IF;
 SELECT * INTO v_row FROM public.project_budget_contributions WHERE budget_cycle_id=p_budget_cycle_id AND work_group_id=p_work_group_id FOR UPDATE;IF v_row.revision<>p_expected_revision THEN RAISE EXCEPTION 'BUDGET_CONTRIBUTION_REVISION_CONFLICT' USING ERRCODE='40001';END IF;
 UPDATE public.project_budget_contributions SET amount=p_amount,note=btrim(COALESCE(p_note,'')),status=p_status,revision=revision+1,updated_by=v_uid,updated_at=now()WHERE budget_cycle_id=p_budget_cycle_id AND work_group_id=p_work_group_id;
 v_result:=jsonb_build_object('budgetCycleId',p_budget_cycle_id,'workGroupId',p_work_group_id,'amount',p_amount,'status',p_status,'revision',p_expected_revision+1);UPDATE public.write_command_requests SET response=v_result,completed_at=now()WHERE id=v_request.id;RETURN v_result||jsonb_build_object('idempotentReplay',false);
END;$$;

CREATE OR REPLACE FUNCTION public.list_my_budget_inbox()RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$
DECLARE v_uid uuid:=auth.uid();BEGIN IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000';END IF;RETURN COALESCE((SELECT jsonb_agg(jsonb_build_object('budgetCycleId',o.budget_cycle_id,'projectId',o.project_id,'projectCode',p.store_code,'projectName',p.shopping_mall_name,'currencyCode',cycle.currency_code,'departmentId',department.id,'departmentCode',department.code,'departmentLabel',department.label,'disciplineId',o.discipline_id,'disciplineCode',d.code,'disciplineLabel',d.label,'departmentName',o.department_name,'assignedAt',o.assigned_at,'unreadCount',(SELECT count(*)FROM public.project_budget_notifications n WHERE n.recipient_user_id=v_uid AND n.budget_cycle_id=o.budget_cycle_id AND n.discipline_id=o.discipline_id AND n.read_at IS NULL))ORDER BY o.assigned_at DESC)FROM public.project_budget_ownerships o JOIN public.projects p ON p.id=o.project_id JOIN public.project_budget_cycles cycle ON cycle.id=o.budget_cycle_id JOIN public.work_ontology_disciplines d ON d.ontology_version_id=o.ontology_version_id AND d.id=o.discipline_id JOIN public.work_ontology_departments department ON department.ontology_version_id=d.ontology_version_id AND department.id=d.department_id WHERE o.owner_user_id=v_uid),'[]'::jsonb);END;$$;

CREATE OR REPLACE FUNCTION public.mark_budget_notifications_read(p_budget_cycle_id uuid,p_discipline_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_uid uuid:=auth.uid();v_count integer;BEGIN IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000';END IF;UPDATE public.project_budget_notifications SET read_at=COALESCE(read_at,now())WHERE recipient_user_id=v_uid AND budget_cycle_id=p_budget_cycle_id AND discipline_id=p_discipline_id AND read_at IS NULL;GET DIAGNOSTICS v_count=ROW_COUNT;RETURN jsonb_build_object('markedRead',v_count);END;$$;

REVOKE ALL ON FUNCTION public.list_budget_owner_candidates(bigint),public.assign_budget_discipline_owner(uuid,uuid,text,uuid,integer,uuid),public.get_project_budget_workspace(bigint),public.save_project_budget_contribution(uuid,uuid,numeric,text,text,integer,uuid),public.list_my_budget_inbox(),public.mark_budget_notifications_read(uuid,uuid)FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.list_budget_owner_candidates(bigint),public.assign_budget_discipline_owner(uuid,uuid,text,uuid,integer,uuid),public.get_project_budget_workspace(bigint),public.save_project_budget_contribution(uuid,uuid,numeric,text,text,integer,uuid),public.list_my_budget_inbox(),public.mark_budget_notifications_read(uuid,uuid)TO authenticated;
